function toHM(m) {
  let h = Math.floor(m / 60);
  let r = m % 60;
  return `${h} h ${r} min`;
}

function grade(mark) {
  if (mark < 0 || mark > 100) {
    return "Invalid";
  } else if (mark >= 80) {
    return "A";
  } else if (mark >= 50) {
    return "B";
  } else {
    return "F";
  }
}

